using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ModifyHeartWithEffectOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ModifyHeartWithEffectOmenData")]
public class ModifyHeartWithEffectOmenData : OnStartOfBattleOmenData
{
	[Header("ModifyHeartWithEffect Omen")]
	[SerializeField]
	private IntEvent OnModifyMaxHearts;

	[SerializeField]
	private int heartsAmount;

	private const string modifyHeartChantID = "ModifyHeartChant";

	[SerializeField]
	private bool enableStartOfTurnOmenData;

	[SerializeField]
	[ShowIf("enableStartOfTurnOmenData")]
	private OnStartOfTurnOmenData onStartOfTurnOmenData;

	[SerializeField]
	private bool addDirectDescriptionBeforeHeartModifiedDescription;

	[SerializeField]
	private bool nadirRing;

	public string ModifyHeartChantID => "ModifyHeartChant";

	public override void Initialize(OmenInstance omenInstance)
	{
		if (nadirRing)
		{
			ReferenceSingleton<CellariusOmensHandler>.Instance.NadirRingOmenActive = true;
		}
		omenInstance.EnqueueOmenFeedbackAndPlay();
		OnModifyMaxHearts.Raise(heartsAmount);
		base.Initialize(omenInstance);
		if (enableStartOfTurnOmenData)
		{
			onStartOfTurnOmenData.Initialize(omenInstance);
		}
	}

	public override void OmenRemoved()
	{
		if (nadirRing)
		{
			ReferenceSingleton<CellariusOmensHandler>.Instance.NadirRingOmenActive = false;
		}
		base.OmenRemoved();
		OnModifyMaxHearts.Raise(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingHearts);
		if (enableStartOfTurnOmenData)
		{
			onStartOfTurnOmenData.OmenRemoved();
		}
	}

	public override string OmenConvertedDescription()
	{
		string text = (enableStartOfTurnOmenData ? (onStartOfTurnOmenData.OmenConvertedDescription() + "\n") : "");
		return base.OmenConvertedDescription() + "\n" + text + (addDirectDescriptionBeforeHeartModifiedDescription ? (GetOmenRawLocalizedDescription() + "\n") : "") + GetModifyHeartsChantLocalizedDescription();
	}

	public string GetModifyHeartsChantLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ModifyHeartChant");
	}
}
